css:
/* From Uiverse.io by sahilxkhadka - Tags: facebook, form, login , loginform */
.__UIV_SCOPE__ .logo {
  margin-bottom: 1rem;
  font-size: 1.2rem;
  text-align: center;
  color: #1877f2;
  font-weight: 700;
}

.__UIV_SCOPE__ form {
  display: flex;
  flex-direction: column;
  background: #fff;
  padding: 1.5rem 1rem;
  width: 300px;
  border-radius: 0.5rem;
  box-shadow: 0 2px 4px rgb(0 0 0 / 10%), 0 8px 16px rgb(0 0 0 / 10%);
}

.__UIV_SCOPE__ form input {
  outline: none;
  padding: 0.4rem 0.5rem;
  margin-bottom: 0.8rem;
  font-size: 0.9rem;
}

.__UIV_SCOPE__ form input:focus {
  border: 1.8px solid #1877f2;
}

.__UIV_SCOPE__ form .login {
  outline: none;
  border: none;
  background: #1877f2;
  padding: 0.8rem 1rem;
  border-radius: 0.4rem;
  font-size: 0.9rem;
  color: #fff;
}

.__UIV_SCOPE__ form .login:hover {
  background: #0f71f1;
  cursor: pointer;
}

.__UIV_SCOPE__ form a {
  text-decoration: none;
  text-align: center;
  font-size: 0.9rem;
  padding-top: 0.8rem;
  color: #1877f2;
}

.__UIV_SCOPE__ form hr {
  background: #f7f7f7;
  margin: 0.5rem;
}

.__UIV_SCOPE__ form .create-account {
  outline: none;
  border: none;
  background: #06b909;
  padding: 0.8rem 1rem;
  border-radius: 0.5rem;
  font-size: 0.9rem;
  color: #fff;
  width: 75%;
  margin: 0 auto;
}

.__UIV_SCOPE__ form .create-account:hover {
  background: #03ad06;
  cursor: pointer;
}
